const copyResponse = $('Generate Slide Copy').first().json;
const meta = $('Build Extract Prompt').first().json;
const content = copyResponse.choices?.[0]?.message?.content;
if (!content) throw new Error('No content from GPT-4o: ' + JSON.stringify(copyResponse));
let parsed;
try { parsed = JSON.parse(content); } catch (e) { throw new Error('Invalid JSON: ' + content.substring(0, 500)); }
const slides = parsed.slides;
if (!slides || !Array.isArray(slides) || slides.length === 0) throw new Error('No slides in response');
const ts = Date.now();
const slidePrompts = meta.slidePrompts;
const enriched = slides.slice(0, 6).map((slide, i) => {
  // Build the actual copy block to pass to GPT so it can render the text
  const copyLines = [];
  if (slide.carouselTitle) copyLines.push(`Carousel title: ${slide.carouselTitle}`);
  if (slide.headline) copyLines.push(`Headline: ${slide.headline}`);
  if (slide.heading) copyLines.push(`Heading: ${slide.heading}`);
  if (slide.subhead) copyLines.push(`Subhead: ${slide.subhead}`);
  if (Array.isArray(slide.bullets) && slide.bullets.length) copyLines.push(`Bullets:\n${slide.bullets.map(b => `- ${b}`).join('\n')}`);
  const copyBlock = copyLines.length ? `\n\nSLIDE COPY (render this text exactly as specified in the layout):\n${copyLines.join('\n')}` : '';
  const finalPrompt = `Do NOT include any logos or brand marks.\n\nBACKGROUND DESCRIPTION:\n${slidePrompts[i]}${copyBlock}\n\nBRAND STYLE:\n${meta.brandDescription}`;
  return {
    originalSlide: slide,
    requestBody: JSON.stringify({ model: 'gpt-image-1.5', prompt: finalPrompt, n: 1, size: '1024x1024' })
  };
});
return [{ json: { slides: enriched, brandId: meta.brandId, layoutId: meta.layoutId, logoUrl: meta.logoUrl, layoutStyle: meta.layoutName, timestamp: ts } }];

const r = $input.first().json;
const meta = $('Parse Slides').first().json;
const i = 0;
const b64 = r.data?.[0]?.b64_json;
if (!b64) throw new Error('Slide 0: no image data: ' + JSON.stringify(r));
const storagePath = `${meta.brandId}/${meta.timestamp}_carousel_slide_${i}.png`;
const imageUrl = null; // set from ImageKit upload response
const binaryData = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), `slide_${i}.png`, 'image/png');
return [{ json: { slideIndex: i, storagePath, imageUrl }, binary: { data: binaryData } }];

